parameters.jsCode:
// Get all rows from Sheet1 (current input)
const allRows = $input.all();

// Per-run cap: process at most N pending rows per execution
const PER_RUN_CAP = 10;

// Filter to pending rows
const pendingRows = allRows.filter(row => {
  const status = (row.json.status || '').toLowerCase().trim();
  return status === 'pending';
});

if (pendingRows.length === 0) {
  console.log('No pending rows to process.');
  return [];
}

// Sort by row_number to process oldest first
pendingRows.sort((a, b) => (a.json.row_number || 0) - (b.json.row_number || 0));

// Take only the first 5
const toProcess = pendingRows.slice(0, PER_RUN_CAP);

console.log(`Pending in sheet: ${pendingRows.length}. Processing ${toProcess.length} this run.`);

return toProcess;
